function extractFunctionAndArguments(topic) {
  var tools = topic.querySelectorAll("tools");
  var functions = [];
  tools.forEach(function(tool) {
    var functionsInTool = tool.querySelectorAll("function");
    for(var i=0; i<functionsInTool.length; i++) {
      var functionInTool = functionsInTool[i];
      var name = functionInTool.querySelector("name").textContent.trim();
      var description = functionInTool.querySelector("description").textContent.trim();
      var parameterObject = {};
      functionInTool.querySelectorAll("parameter").forEach(function(parameter) {
        var result = parameter.querySelectorAll("result");
        var prop = parameter.querySelector("name").textContent.trim().trim().replace(/[\""]+/g,"") 
        prop = prop.split(/ +/g);
        if(result.length>0){
        prop = result[0].lines(Infinity)[0].querySelectorText();
        }
        prop = prop.trim();
        result = parameter.querySelectorAll("result");
        if(result.length>0) result=result[0];
        var value = result.querySelector("value");
        var type = value.querySelector("type").textContent.trim();
        var required = value.querySelectorAll("required");
        var required = false;
        if(required.length>0) required=true;
        parameterObject[prop] = { type:type, value:value.querySelector("value").textContent.trim(), required:required };
      });
      functions.push({ name:name, description:description, parameters:parameterObject});
    }
  });
  return{ functions};
}

