function find_coordinates(coord_a, coord_b, max_distance) {
  function generate_distance_coords(coord_a, coord_b, num_iterations) {
    const distance = Math.hypot(coord_b[0] - coord_a[0], coord_b[1] - coord_a[1]);
    const angle_between = Math.atan2(coord_b[1] - coord_a[1], coord_b[0] - coord_a[0]);
    let coords = coord_a;
    for (let i = 1; i <= num_iterations; i++) {
      const x = Math.sin(angle_between + Math.PI / 3) * i * distance;
      const y = Math.cos(angle_between + Math.PI / 3) * i * distance;
      coords = [coords[0] + x, coords[1] + y];
      if (is_point_in_circle(coords, coord_b, max_distance)) break;
    }
    return coords;
  }

  function is_point_in_circle(coords, center, radius) {
    const distance = Math.hypot(coords[0] - center[0], coords[1] - center[1]);
    return distance <= radius;
  }

  return generate_distance_coords(coord_a, coord_b, 100).join(' ');
