# Import required modules
import requests

class QwenBot:
    def __init__(self, api_key):
        self._api_key = api_key
        self._api_url = 'https://api.qwen.ai/'
        self._cancel = False

    def calculator(self, expression):
        if self._cancel:
            return ""
        response = requests.get(f'{self._api_url}calculator/v1/{self._api_key}{expression}', timeout=20)
        if response.status_code == 200:
            return int(response.text)
        else:
            return "Error: Unable to calculate expression."

    def delete_calendar_event(self, event_id):
        if self._cancel:
            return False
        response = requests.get(f'{self._api_url}delete_calendar_event/v1/{self._api_key}{event_id}')
        if response.status_code == 200:
            return True
        else:
            return False

    def search_contacts(self, query):
        if self._cancel:
            return []
        response = requests.get(f'{self._api_url}search_contacts/v1/{self._api_key}{query}', timeout=20)
        contacts = response.json()
        return contacts

    def send_email(self, to, subject, body):
        if self._cancel:
            return False
        response = requests.post(f'{self._api_url}send_email/v1/{self._api_key}', data={'to': to, 'subject': subject, 'body': body})
        if response.status_code == 200:
            return True
        return "Error: Unable to send the email."

    def say(self, text):
        if self._cancel:
            return False
        response = requests.post(f'{self._api_url}say/v1/{self._api_key}', data={'text': text})
        if response.status_code == 200:
            return True
        else:
            return "Error: Unable to say the sentence."

