function get_calendar_event(desired_date) {
    // Get calendar calendar events that are after the desiredDate, with suggestions of october 5, 2024.
    var calendar_events = db.collection('calendar').where('date', '>', desired_date).get().then((querySnapshot) => {
        return querySnapshot.docs.map((event) => ({
            title: event.data().title,
            notes: event.data().notes,
            date: event.data().date,
            startTime: new Date(event.data().start_time),
            endTime: new Date(event.data().end_time),
            attendees: event.data().attendees
        }));
    });

    return calendar_events;
}

function search_contacts(query) {
    // Find contacts with names containing the query
    var search_results = db.collection('contacts').where('name', 'array-contains-any', query).get().then((querySnapshot) => {
        return querySnapshot.docs.map((contact) => ({
            username: contact.data().username,
            picture: contact.data().photoURL,
            team: contact.data().team,
            email: contact.data().email
        }));
    });

    return search_results;
}

function send_email(to, subject, body) {
    // Send an email to the recipient
    var service = Gmail.createService();
    service.setUserCredential(service, email, api_key);

    var message = {
        'to': to,
        'subject': subject,
        'html': body
    };

    service.users.messages.send(message, '', function(err) {
        if (err) {
            throw err;
        }
    });
}

